import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, SRGBColorSpace } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const Group_ = THREE?.Group ?? Group;
  const Mesh_ = THREE?.Mesh ?? Mesh;
  const PlaneGeometry_ = THREE?.PlaneGeometry ?? PlaneGeometry;

  const group = new Group_();
  group.name = 'journal-card-2';

  // Atlas region 512x320 -> aspect 1.6
  const rect = { w: 512, h: 320 };
  const aspect = rect.w / rect.h;
  const height = 1.8;
  const width = height * aspect;

  const geometry = new PlaneGeometry_(width, height, 1, 1);

  // ---- engineered gradient + accent edge color node (built once, extended with grain when texture arrives)
  function buildColorNode(grainTexNode) {
    const uvNode = uv();
    const topColor = vec3(0x16 / 255, 0x16 / 255, 0x1d / 255); // ink
    const bottomColor = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255); // surface
    const gradient = mix(bottomColor, topColor, uvNode.y);

    const accentColor = vec3(1.0, 0x2a / 255, 0x38 / 255); // signal red accent
    const edgeMask = smoothstep(0.02, 0.0, uvNode.x); // thin spine on left edge, <10% of frame

    let base = mix(gradient, accentColor, edgeMask.mul(0.85));

    if (grainTexNode) {
      const grain = grainTexNode.r.mul(0.28).add(0.86); // subtle grain modulation 0.86-1.14
      base = base.mul(grain);
    }
    return base;
  }

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1,
  });
  material.colorNode = buildColorNode(null);

  const mesh = new Mesh_(geometry, material);
  mesh.position.set(0, 0, 0);
  group.add(mesh);

  let loadedTexture = null;

  const imageUrl = config.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader
      .loadTexture(imageUrl)
      .then((tex) => {
        if (!tex) return;
        if (SRGBColorSpace) tex.colorSpace = SRGBColorSpace;
        loadedTexture = tex;
        material.colorNode = buildColorNode(texture(tex));
        material.needsUpdate = true;
      })
      .catch(() => {
        // silently keep gradient-only surface on load failure
      });
  }

  // ---- weighted-settle entrance (static composition thereafter, per spec)
  gsap.set(mesh.position, { y: -0.15 });
  gsap.set(mesh.scale, { x: 0.98, y: 0.98, z: 1 });
  material.opacity = 0;

  const timeline = gsap.timeline();
  timeline.to(mesh.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  timeline.to(
    mesh.scale,
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0
  );
  timeline.to(material, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timeline.kill();
    geometry.dispose();
    material.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
  };

  return group;
}
